import React, { useState } from 'react';
import Sidebar from './Sidebar'; // ඔයාගේ Sidebar component එක

export default function AdminDashboard({ userName, onLogoutClick }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', overflow: 'hidden' }}>
      
      {/* 1. Header (සුදු පාට තීරුව - උඩම තියෙන්නේ) */}
      <header style={{ 
        height: '70px', 
        backgroundColor: '#ffffff', 
        display: 'flex', 
        alignItems: 'center', 
        padding: '0 30px', 
        borderBottom: '1px solid #e2e8f0',
        zIndex: 10
      }}>
         <img src="/path-to-your-logo.png" alt="Logo" style={{ height: '40px' }} />
         <div style={{ marginLeft: '20px', fontWeight: 'bold', fontSize: '18px', color: '#1e293b' }}>
           AuraPen Saku
         </div>
         <div style={{ marginLeft: 'auto', fontWeight: '600', color: '#334155' }}>
           Welcome, Admin User 👋
         </div>
      </header>

      {/* 2. පහළ කොටස (Sidebar + Content එක එක පේළියට) */}
      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        
        {/* Sidebar එක */}
        <div style={{ width: '260px', backgroundColor: '#15803d' }}>
          <Sidebar 
            currentSubPage={currentSubPage} 
            setCurrentSubPage={setCurrentSubPage} 
            onLogoutClick={onLogoutClick} 
          />
        </div>

        {/* දකුණු පැත්තේ Content එක */}
        <div style={{ flex: 1, padding: '20px', overflowY: 'auto', backgroundColor: '#f1f5f9' }}>
          <h2>{currentSubPage}</h2>
          {/* මෙතනට ඔයාගේ චාට්ස් සහ කාඩ්ස් එනවා */}
          <div style={{ marginTop: '20px' }}>
            <p>දත්ත ටික මෙතන පෙන්වන්න...</p>
          </div>
        </div>
      </div>
    </div>
  );
}
